package net.officefloor.hq.app.person;

import jakarta.validation.Valid;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

public class ValidatePersonRequest {

    private static final Set<String> GRADES = Set.of("A", "B", "C");

    public void validate(@RequestBody @Valid PersonRequest request, Out<PersonRequest> body)
            throws InvalidPersonException {
        // The name is kept without surrounding spaces; a blank one is refused.
        String name = request.name() == null ? "" : request.name().strip();
        if (name.isBlank()) {
            throw new InvalidPersonException("A name is required.");
        }
        String grade = request.grade() == null ? "" : request.grade().trim().toUpperCase();
        if (!GRADES.contains(grade)) {
            throw new InvalidPersonException("The grade must be A, B or C.");
        }
        String from = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!from.isEmpty()) {
            try {
                LocalDate.parse(from);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The grade's from-date must be yyyy-mm-dd.");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !terms.matches("\\d{1,5}")) {
            throw new InvalidPersonException("The terms must be a whole number of days, 0 or more, or blank.");
        }
        String termsFrom = request.termsFrom() == null ? "" : request.termsFrom().trim();
        if (!termsFrom.isEmpty()) {
            try {
                LocalDate.parse(termsFrom);
            } catch (DateTimeParseException e) {
                throw new InvalidPersonException("The terms' from-date must be yyyy-mm-dd.");
            }
        }
        String contact = request.contact() == null ? "" : request.contact().strip().toLowerCase(Locale.ROOT);
        String tags = request.tags() == null ? null : Claim.tags(request.tags());
        body.set(new PersonRequest(name, grade, from, request.version(),
                terms.isEmpty() ? "" : String.valueOf(Integer.parseInt(terms)), contact,
                request.tags() == null ? null : tags == null ? "" : tags, termsFrom));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import net.officefloor.hq.app.sheet.SheetRepository;
import java.util.Objects;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Applies the edit to the person as loaded; refused when the editor loaded an older version. The form's grade
 * is recorded from its from-date (blank: the sheet's today), keeping the grades already recorded — except that a
 * grade left as the row showed it, with the from-date blank, records nothing. The person's own terms are recorded
 * likewise from the terms' from-date (blank: from the beginning of time; blank terms: none), keeping those recorded
 * from other dates — except that terms left as the row showed them, with the from-date blank, record nothing. Their
 * contact becomes the form's; whether terms were recorded (even the same as those already recorded) or the contact
 * changed is published for the audit.
 */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, SheetRepository sheets, Out<Person> updated,
            Out<PersonTermsChange> termsChange) throws StalePersonException {
        if (request.version() != null && request.version() != person.version()) {
            throw new StalePersonException(person.name());
        }
        LocalDate today = sheets.today(person.sheetId());
        Integer terms = request.termsDays();
        LocalDate termsFrom = request.termsFromDate();
        boolean recorded = termsFrom != null || !Objects.equals(terms, person.terms());
        Person termed = recorded ? person.withTerms(terms, termsFrom, today) : person;
        String contact = request.contactOrNull();
        termsChange.set(new PersonTermsChange(recorded,
                !Objects.equals(contact, person.contact())));
        boolean blank = request.gradeFrom() == null || request.gradeFrom().isEmpty();
        if (blank && request.grade().equals(person.grade())) {
            updated.set(termed.withName(request.name()).withContact(contact));
            return;
        }
        LocalDate from = blank ? today : LocalDate.parse(request.gradeFrom());
        updated.set(termed.withNameAndGrade(request.name(), request.grade(), from, today).withContact(contact));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildPerson {
    public void build(@Val PersonRequest request, @Val Sheet sheet, Out<Person> person) {
        Person built = new Person(null, sheet.id(), request.name(), request.grade(), 0, 0, null, null, null, List.of())
                .withContact(request.contactOrNull());
        // terms with a from-date are recorded from it, none of their own before it
        person.set(request.termsFromDate() == null ? built.withTerms(request.termsDays())
                : built.withTerms(request.termsDays(), request.termsFromDate(),
                        sheet.today() == null ? java.time.LocalDate.now() : sheet.today()));
    }
}
