import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/**
 * Clones a sheet to a new id: the clone gets its today, settings, roles, rates (with their versions), holidays, void reasons, templates,
 * people (grades, terms, contacts, aliases, tags, holds, retirements, patrons), pools, crews, periods (all open) and claims
 * (status, frozen figures, dates, notes, logs). Statements, watches, comments, locks, batches and as-of days are not
 * copied. Claims that had a number take the clone's own numbers afresh, in the order they were opened.
 */
@Repository
public class SheetCloner {

    /** The tables kept per sheet that are copied as they are, under the clone's id. */
    private static final List<String> SHEET_TABLES = List.of("user_role", "permission", "delegation", "setting_from",
            "grade_terms", "rate", "rate_version", "holiday", "void_reason", "claim_template", "claim_tag", "sheet_pot");

    /** The tables of a person's own entries, copied under the clone's id and the person's id there. */
    private static final List<String> PERSON_TABLES = List.of("person_grade", "person_terms", "person_hold",
            "person_alias", "person_retirement");

    private final JdbcTemplate jdbc;

    private final ClaimRepository claims;

    private final SheetRepository sheets;

    private final SettingRepository settings;

    private final PeriodRepository periods;

    public SheetCloner(JdbcTemplate jdbc, ClaimRepository claims, SheetRepository sheets, SettingRepository settings,
            PeriodRepository periods) {
        this.jdbc = jdbc;
        this.claims = claims;
        this.sheets = sheets;
        this.settings = settings;
        this.periods = periods;
    }

    /** Clone the sheet {@code from} to the never-used id {@code to}. */
    public void cloneSheet(String from, String to) {
        Map<String, Object> sheet = new HashMap<>();
        sheet.put("id", to);
        sheet.put("archived", false);
        sheet.put("last_claim_number", 0);
        sheet.put("last_batch", 0);
        sheet.put("cloned_from", from);
        RowCopy.copyAll(jdbc, "sheet", "id = ?", List.of(from), null, sheet);
        Map<String, Object> onClone = Map.of("sheet_id", to);
        for (String table : SHEET_TABLES) {
            RowCopy.copyAll(jdbc, table, "sheet_id = ?", List.of(from), null, onClone);
        }
        Map<String, Object> open = new HashMap<>(onClone);
        open.put("closed", false);
        open.put("soft_closed", false);
        open.put("closed_total", null);
package net.officefloor.hq.app.holiday;

import jakarta.validation.Valid;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestBody;

/** Refuses (400) a holiday whose date is not yyyy-mm-dd or is already on the sheet's list. */
public class ValidateHolidayRequest {
    public void validate(@Val Sheet sheet, @RequestBody @Valid HolidayRequest request, HolidayRepository holidays,
            Out<Holiday> holiday) throws InvalidHolidayException {
        String text = request.date() == null ? "" : request.date().trim();
        LocalDate date;
        try {
            date = LocalDate.parse(text);
        } catch (DateTimeParseException e) {
            throw new InvalidHolidayException("A holiday's date must be yyyy-mm-dd.");
        }
        if (holidays.exists(sheet.id(), date)) {
            throw new InvalidHolidayException(date + " is already a holiday.");
        }
        holiday.set(new Holiday(sheet.id(), date));
    }
}
# Add a date (yyyy-mm-dd) to the sheet's holidays (HOLIDAY_ADDED); a date not yyyy-mm-dd or one already on the
# list is refused (400). Every claim that is not SETTLED or VOID and is due by on or after the new holiday has its due-by
# worked out again from its date, with the terms it was fixed with, over the holidays now on the sheet; ROLLUP/TOTALS
# follow HOLIDAY_ADDED when any figure moved. Responds with the sheet's holidays, earliest first.
