  class: net.officefloor.hq.app.holiday.ValidateHolidayRequest
  govern: [ transaction ]
  next: before
before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.holiday.SaveHoliday
  govern: [ transaction ]
  next: refix
refix:
  class: net.officefloor.hq.app.holiday.RefixDueBys
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.holiday.AuditHolidayAdded
  govern: [ transaction ]
  next: rollup
